import type { BankQuestion } from "@/lib/bank";

/** Electrostatics and Capacitance (Physics (JEE/NEET)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-electrostatics-1","question":"Two point charges of 2 μC and 3 μC are placed 30 cm apart in air. The electrostatic force between them is (k = 9 × 10⁹ N·m²/C²):","options":["0.6 N","0.06 N","6 N","0.3 N"],"answer":0,"explanation":"F = kq₁q₂/r² = 9 × 10⁹ × 2 × 10⁻⁶ × 3 × 10⁻⁶ / (0.3)² = 0.054/0.09 = 0.6 N. Forgetting to square 0.3 m gives the wrong 0.18 N.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-2","question":"Which of the following is NOT a unit of electric field?","options":["N/C","V/m","J/C","J/(C·m)"],"answer":2,"explanation":"J/C is the volt, the unit of potential, not of field. N/C and V/m are the standard units; J/(C·m) = V/m is also a field unit.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-electrostatics-3","question":"A parallel-plate capacitor has capacitance C. If the separation between its plates is doubled (nothing else changed), the capacitance becomes:","options":["2C","C/2","4C","C/4"],"answer":1,"explanation":"C = ε₀A/d, so capacitance is inversely proportional to the plate separation: doubling d halves C.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-electrostatics-4","question":"A hollow metal sphere of radius 10 cm is charged so that the potential on its surface is 100 V. The potential at the centre of the sphere is:","options":["Zero","50 V","100 V","Cannot be determined without the charge"],"answer":2,"explanation":"Inside a conductor the field is zero, so the potential is constant and equal to the surface value: 100 V. Answering zero confuses field with potential.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-5","question":"A point charge q is placed at the centre of a cube of side a. The electric flux through any one face of the cube is:","options":["q/ε₀","q/(6ε₀)","q/(3ε₀)","q/(6ε₀a²)"],"answer":1,"explanation":"By Gauss's law the total flux through the cube is q/ε₀; by symmetry each of the six faces gets one-sixth: q/(6ε₀). The side length does not enter the answer.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-6","question":"A 10 μF capacitor is charged to 100 V. The energy stored in it is:","options":["0.5 J","0.05 J","5 × 10⁻³ J","0.1 J"],"answer":1,"explanation":"U = ½CV² = ½ × 10 × 10⁻⁶ × (100)² = ½ × 10⁻⁵ × 10⁴ = 0.05 J.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-electrostatics-7","question":"For a short electric dipole, the ratio of the electric field on the axial line to that on the equatorial line, at the same distance r from the centre, is:","options":["1 : 1","1 : 2","2 : 1","4 : 1"],"answer":2,"explanation":"E_axial = 2kp/r³ and E_equatorial = kp/r³, so the ratio is 2 : 1. The directions also differ: the axial field is along p, the equatorial field is opposite to p.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-8","question":"Three capacitors of 6 μF each are first connected in series and then in parallel. The ratio of the parallel to the series equivalent capacitance is:","options":["3 : 1","1 : 9","9 : 1","6 : 1"],"answer":2,"explanation":"Series: 6/3 = 2 μF. Parallel: 6 × 3 = 18 μF. Ratio = 18/2 = 9 : 1. For n equal capacitors the ratio is always n².","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-electrostatics-9","question":"A charge of 2 μC is moved from point A to point B, both lying on an equipotential surface of 50 V. The work done by the external agent is:","options":["100 μJ","Zero","50 μJ","−100 μJ"],"answer":1,"explanation":"W = qΔV and ΔV = 0 between two points of the same equipotential surface, so the work done is zero. The value 50 V itself is a distractor.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-10","question":"Three identical charges q are placed at the corners of an equilateral triangle of side a. The magnitude of the net force on any one charge is:","options":["kq²/a²","√2 kq²/a²","√3 kq²/a²","2kq²/a²"],"answer":2,"explanation":"Each of the other two charges exerts kq²/a², the two forces making 60° with each other. Resultant = 2 × (kq²/a²) × cos 30° = √3 kq²/a², directed away from the centroid.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-11","question":"Charges q, q, q and −q are placed at the four corners of a square of side a. The electric potential at the centre of the square is:","options":["Zero","√2 kq/a","2√2 kq/a","4√2 kq/a"],"answer":2,"explanation":"Each charge is at distance a/√2 from the centre, so each contributes ±√2 kq/a. Sum = (1 + 1 + 1 − 1) × √2 kq/a = 2√2 kq/a. Potential is a scalar, so there is no vector cancellation.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-12","question":"A capacitor is charged by a battery to stored energy U, and the battery is then disconnected. A dielectric slab of dielectric constant 3 is now inserted to fill the gap completely. The stored energy becomes:","options":["3U","9U","U","U/3"],"answer":3,"explanation":"With the battery removed the charge Q is fixed. U = Q²/(2C) and C becomes 3C, so the energy falls to U/3; the difference is the work done by the field in pulling the slab in. With the battery still connected the energy would instead rise to 3U.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-13","question":"An infinitely long straight wire carries a uniform linear charge density of 2 μC/m. The electric field at a distance of 10 cm from the wire is (k = 9 × 10⁹ SI units):","options":["1.8 × 10⁵ N/C","3.6 × 10⁴ N/C","7.2 × 10⁵ N/C","3.6 × 10⁵ N/C"],"answer":3,"explanation":"By Gauss's law E = λ/(2πε₀r) = 2kλ/r = 2 × 9 × 10⁹ × 2 × 10⁻⁶ / 0.1 = 3.6 × 10⁵ N/C. Using kλ/r (dropping the factor 2) gives the wrong 1.8 × 10⁵ N/C.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-14","question":"An electric dipole of moment 4 × 10⁻⁹ C·m is placed in a uniform field of 5 × 10⁴ N/C with its moment parallel to the field. The work required to rotate it until it is antiparallel to the field is:","options":["2 × 10⁻⁴ J","8 × 10⁻⁴ J","Zero","4 × 10⁻⁴ J"],"answer":3,"explanation":"U = −pE cos θ. W = U(180°) − U(0°) = pE − (−pE) = 2pE = 2 × 4 × 10⁻⁹ × 5 × 10⁴ = 4 × 10⁻⁴ J. Rotating only to 90° would need pE = 2 × 10⁻⁴ J.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-15","question":"A conducting sphere of radius 20 cm is at a potential of 6000 V (relative to infinity). The electric field just outside its surface is:","options":["1.2 × 10³ V/m","1.2 × 10⁵ V/m","3 × 10³ V/m","3 × 10⁴ V/m"],"answer":3,"explanation":"For a charged sphere V = kQ/R and E = kQ/R², so E = V/R = 6000/0.2 = 3 × 10⁴ V/m. The charge itself is not needed.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-16","question":"A 2 μF capacitor charged to 100 V and a 4 μF capacitor charged to 40 V are connected in parallel with plates of the same polarity joined. The energy lost in the process is:","options":["1.2 mJ","Zero","3.6 mJ","2.4 mJ"],"answer":3,"explanation":"Common potential V = (200 + 160) μC / 6 μF = 60 V. Initial energy = ½(2)(100)² + ½(4)(40)² μJ = 10000 + 3200 = 13200 μJ. Final = ½(6)(60)² = 10800 μJ. Loss = 2400 μJ = 2.4 mJ, dissipated as heat in the connecting wires.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-17","question":"A proton and an α-particle, both initially at rest, are accelerated through the same potential difference. The ratio of the speed of the proton to that of the α-particle is:","options":["1 : 1","1 : √2","2 : 1","√2 : 1"],"answer":3,"explanation":"½mv² = qV gives v ∝ √(q/m). For the proton q/m ∝ 1/1; for the α-particle q/m ∝ 2/4 = 1/2. So v_p : v_α = 1 : 1/√2 = √2 : 1. (Their kinetic energies are in the ratio 1 : 2.)","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-18","question":"A short dipole has moment 2 × 10⁻⁹ C·m. The potential at a point 10 cm from its centre, on a line making 60° with the dipole axis, is (k = 9 × 10⁹ SI units):","options":["450 V","900 V","225 V","Zero"],"answer":0,"explanation":"V = kp cos θ / r² = 9 × 10⁹ × 2 × 10⁻⁹ × cos 60° / (0.1)² = 18 × 0.5 / 0.01 = 900 V × 0.5 = 450 V. On the axis (θ = 0) it would be 900 V; on the equatorial line it is zero.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-19","question":"How many of the following statements about Gauss's law are correct? (A) The net flux through a closed surface depends only on the net charge enclosed by it. (B) The electric field at a point on a Gaussian surface depends only on the charge enclosed by that surface. (C) Gauss's law holds for a closed surface of any shape. (D) If the net flux through a closed surface is zero, the electric field must be zero at every point of the surface.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(A) and (C) are correct. (B) is wrong: the field at a point is due to all charges, inside and outside; only the total flux is fixed by the enclosed charge. (D) is wrong: an enclosed dipole, or a charge outside the surface, gives zero net flux with a non-zero field on the surface.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-20","question":"A parallel-plate capacitor of capacitance C₀ (plate separation d) has a dielectric slab of dielectric constant 3 and thickness d/2 inserted between its plates. Its new capacitance is:","options":["1.5 C₀","2 C₀","3 C₀","0.75 C₀"],"answer":0,"explanation":"The gap acts as two capacitors in series: air of thickness d/2 and dielectric of thickness d/2. C = ε₀A / (d/2 + d/(2K)) = 2Kε₀A / (d(K + 1)). With K = 3: C = (6/4) ε₀A/d = 1.5 C₀. Filling the whole gap would give 3 C₀.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-21","question":"Two concentric conducting spherical shells have radii 10 cm (inner) and 20 cm (outer). The outer shell carries a charge of +4 μC and the inner shell is earthed. The charge that appears on the inner shell is:","options":["−2 μC","−4 μC","−1 μC","Zero"],"answer":0,"explanation":"The earthed inner shell must be at zero potential: kq'/a + kQ/b = 0 (its own charge q' acts from radius a, the outer charge Q gives kQ/b everywhere inside the outer shell). So q' = −Qa/b = −4 × (10/20) = −2 μC. The tempting −4 μC is the answer only when the OUTER shell is the earthed one.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-22","question":"A capacitor C₀ is connected to a battery of emf V and, with the battery still connected, a dielectric slab of dielectric constant K = 2 is slowly inserted to fill the gap. The ratio of the work done by the battery to the increase in the energy stored in the capacitor is:","options":["2 : 1","1 : 1","1 : 2","4 : 1"],"answer":0,"explanation":"Charge rises from C₀V to 2C₀V, so the battery supplies ΔQ = C₀V at potential V: W_battery = C₀V². Energy rises from ½C₀V² to ½(2C₀)V², an increase of ½C₀V². Ratio = 2 : 1; the other half of the battery's work is done by the field in pulling the slab in (released as heat if the slab is held).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-23","question":"Assertion (A): Electrostatic field lines never form closed loops. Reason (R): The electrostatic field is conservative, so the work done by it around any closed path is zero.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"If a field line were a closed loop, moving a charge once around it would give non-zero work (the field is along the path everywhere), contradicting the conservative nature of the electrostatic field. So R correctly explains A. (Induced electric fields in EMI are non-conservative and do form closed loops.)","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-electrostatics-24","question":"A pendulum bob of mass 10 g carrying a charge of 20 μC hangs from a light string in a uniform horizontal electric field of 5000 N/C. In equilibrium the tension in the string is (g = 10 m/s²):","options":["0.141 N","0.1 N","0.2 N","0.05 N"],"answer":0,"explanation":"qE = 20 × 10⁻⁶ × 5000 = 0.1 N and mg = 0.01 × 10 = 0.1 N, so tan θ = qE/mg = 1 and the string makes 45° with the vertical. Tension T = √((qE)² + (mg)²) = 0.1√2 ≈ 0.141 N.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-25","question":"A thin ring of radius R carries a uniformly distributed charge Q. A particle of mass m and charge −q is released from rest on the axis of the ring at a distance √3 R from its centre. Its speed when it reaches the centre is (ignore gravity):","options":["√(2kQq/(mR))","√(kQq/(2mR))","√(kQq/(mR))","√(3kQq/(2mR))"],"answer":2,"explanation":"Potential on the axis V(x) = kQ/√(R² + x²). At x = √3 R: V = kQ/(2R); at the centre V = kQ/R. Energy conservation for charge −q: ½mv² = (−q)(V_initial − V_final) = q(kQ/R − kQ/(2R)) = kQq/(2R), so v = √(kQq/(mR)).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-26","question":"Capacitors of 3 μF and 6 μF are connected in series across a 90 V battery. The energy stored in the 3 μF capacitor is:","options":["2.7 mJ","5.4 mJ","10.8 mJ","8.1 mJ"],"answer":1,"explanation":"Series capacitance = 2 μF, so the charge on each capacitor is Q = 2 × 90 = 180 μC. Energy in 3 μF = Q²/(2C) = (180 × 10⁻⁶)² / (2 × 3 × 10⁻⁶) = 5.4 × 10⁻³ J = 5.4 mJ. In series the smaller capacitor stores more energy (ratio 2 : 1).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-27","question":"A non-conducting solid sphere of radius R carries charge Q distributed uniformly throughout its volume. The ratio of the electric field at a distance R/2 from the centre to that at a distance 2R from the centre is:","options":["1 : 1","2 : 1","1 : 2","4 : 1"],"answer":1,"explanation":"Inside, E = kQr/R³, so at r = R/2: E = kQ/(2R²). Outside, E = kQ/r², so at r = 2R: E = kQ/(4R²). Ratio = 2 : 1. For a conducting (or hollow) sphere the inside field would be zero.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-28","question":"How many of the following statements about a parallel-plate capacitor with a dielectric are correct? (A) Inserting a dielectric while the battery stays connected increases the charge on the plates. (B) Inserting a dielectric after the battery is disconnected decreases the stored energy. (C) For the purpose of capacitance, the dielectric constant of a metal is taken as infinite. (D) The induced surface charge on the dielectric equals the free charge on the plate multiplied by (1 − 1/K).","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. With V fixed, Q = KC₀V rises; with Q fixed, U = Q²/(2KC₀) falls; a metal slab reduces the field inside to zero, which corresponds to K → ∞; and the induced charge is Q(1 − 1/K), which gives the field reduced by the factor K.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-electrostatics-29","question":"Match the location (List I) with the magnitude of the electric field there (List II). List I: (P) just outside the surface of a charged conductor with surface charge density σ; (Q) near a thin infinite non-conducting sheet of surface charge density σ; (R) at the centre of a uniformly charged spherical shell; (S) at distance r from an infinite line charge λ. List II: (1) σ/(2ε₀); (2) λ/(2πε₀r); (3) σ/ε₀; (4) zero.","options":["P-1, Q-3, R-4, S-2","P-3, Q-1, R-4, S-2","P-3, Q-1, R-2, S-4","P-1, Q-3, R-2, S-4"],"answer":1,"explanation":"Just outside a conductor E = σ/ε₀ (all the field is on one side); for a thin sheet E = σ/(2ε₀) (field on both sides); inside a shell the field is zero; for a line charge E = λ/(2πε₀r). The P/Q factor-of-2 swap is the usual trap.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-30","question":"A proton (take q/m = 10⁸ C/kg) enters a region of uniform electric field E = 200 N/C with velocity 10⁵ m/s perpendicular to the field. The field region is 10 cm long along the initial velocity. The deflection of the proton on leaving the field is:","options":["0.5 cm","1 cm","2 cm","4 cm"],"answer":1,"explanation":"Time in the field t = L/v = 0.1/10⁵ = 10⁻⁶ s. Acceleration a = qE/m = 10⁸ × 200 = 2 × 10¹⁰ m/s². Deflection y = ½at² = ½ × 2 × 10¹⁰ × 10⁻¹² = 10⁻² m = 1 cm; the motion is a parabola exactly like a projectile.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-31","question":"The number of electrons that together carry a charge of 1 coulomb is about (e = 1.6 × 10⁻¹⁹ C):","options":["6.25 × 10¹⁹","1.6 × 10⁻¹⁹","1.6 × 10¹⁹","6.25 × 10¹⁸"],"answer":3,"explanation":"n = q/e = 1/(1.6 × 10⁻¹⁹) = 6.25 × 10¹⁸.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-electrostatics-32","question":"The electric field at a distance of 3 m from a point charge of 9 μC in air is (k = 9 × 10⁹ N m²/C²):","options":["3 × 10³ N/C","2.7 × 10⁴ N/C","9 × 10³ N/C","8.1 × 10⁴ N/C"],"answer":2,"explanation":"E = kq/r² = 9 × 10⁹ × 9 × 10⁻⁶/9 = 9 × 10³ N/C. Dividing by r instead of r² gives 2.7 × 10⁴ N/C, which is the potential in volts.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-33","question":"Point charges of 1 μC and 2 μC are 1 m apart in air. The electrostatic potential energy of the pair is (k = 9 × 10⁹ N m²/C²):","options":["0.18 J","0.018 J","0.009 J","0.036 J"],"answer":1,"explanation":"U = kq₁q₂/r = 9 × 10⁹ × 2 × 10⁻¹²/1 = 1.8 × 10⁻² J.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-electrostatics-34","question":"Capacitors of 2 μF and 3 μF are connected in series across a 10 V battery. The charge on each capacitor is:","options":["12 μC","30 μC","50 μC","20 μC"],"answer":0,"explanation":"C_series = (2 × 3)/(2 + 3) = 1.2 μF, and in series every capacitor carries the same charge Q = 1.2 × 10 = 12 μC. 50 μC would be the total for a parallel connection.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-35","question":"A large plane sheet carries a uniform surface charge density of 8.85 × 10⁻⁶ C/m². The electric field near it, away from its edges, is (ε₀ = 8.85 × 10⁻¹² C²/N m²):","options":["5 × 10⁵ N/C","1 × 10⁶ N/C","2.5 × 10⁵ N/C","1 × 10⁵ N/C"],"answer":0,"explanation":"For a thin sheet E = σ/2ε₀ = 8.85 × 10⁻⁶/(2 × 8.85 × 10⁻¹²) = 5 × 10⁵ N/C, independent of distance. σ/ε₀ (10⁶ N/C) applies just outside a charged conductor.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-36","question":"An electric dipole of moment 2 × 10⁻⁸ C m is placed in a uniform field of 10⁴ N/C with its axis at 30° to the field. The torque on it is:","options":["1 × 10⁻⁴ N m","0.5 × 10⁻⁴ N m","2 × 10⁻⁴ N m","1.73 × 10⁻⁴ N m"],"answer":0,"explanation":"τ = pE sinθ = 2 × 10⁻⁸ × 10⁴ × ½ = 10⁻⁴ N m. Using cos30° gives 1.73 × 10⁻⁴, which is not the torque.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-electrostatics-37","question":"A parallel-plate capacitor of capacitance C₀ has half the area between its plates filled with a dielectric slab of constant 3 occupying the full gap, the other half being air. Its capacitance becomes:","options":["1.5C₀","4C₀","2C₀","3C₀"],"answer":2,"explanation":"The two halves act as capacitors in parallel: (C₀/2) × 3 + C₀/2 = 2C₀. 1.5C₀ is the answer for a slab filling half the gap across the full area (series arrangement).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-38","question":"Two conducting spheres of radii 1 cm and 3 cm, far apart, are connected by a thin wire and given a total charge. The ratio of the surface charge density on the smaller sphere to that on the larger is:","options":["9 : 1","3 : 1","1 : 1","1 : 3"],"answer":1,"explanation":"Connected conductors are at the same potential, kQ/r, so Q ∝ r and σ = Q/4πr² ∝ 1/r. Hence σ_small/σ_large = 3/1, which is why charge concentrates at sharp points.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-electrostatics-39","question":"A thin semicircular ring of radius R carries a charge Q distributed uniformly. The magnitude of the electric field at its centre is:","options":["zero","Q/(4π²ε₀R²)","Q/(2π²ε₀R²)","Q/(4πε₀R²)"],"answer":2,"explanation":"With λ = Q/πR, the components along the diameter cancel and the rest add to E = 2kλ/R = 2kQ/(πR²) = Q/(2π²ε₀R²). It is zero only for a complete ring.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-40","question":"An isolated parallel-plate capacitor with plate area A and plate separation d carries charge Q. The work needed to pull the plates apart slowly until the separation is 2d is:","options":["Q²d/(4ε₀A)","Q²d/(2ε₀A)","2Q²d/(ε₀A)","Q²d/(ε₀A)"],"answer":1,"explanation":"With Q fixed, the attraction between the plates is F = Q²/(2ε₀A), constant with distance, so W = F × d = Q²d/(2ε₀A). This equals the increase in stored energy Q²/2C as C halves.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-41","question":"How many of the following statements about a conductor in electrostatic equilibrium are correct?\n(A) The electric field inside the conductor is zero.\n(B) The surface of the conductor is an equipotential.\n(C) Surface charge density is greatest where the radius of curvature is largest.\n(D) The electric field just outside the surface is perpendicular to it.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and D are correct. C is wrong: charge density is greatest where the radius of curvature is smallest (sharp points), the basis of corona discharge and lightning conductors. So only three are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-electrostatics-42","question":"The electric potential in a region is V = (4x² + 3y) volt, with x and y in metres. The magnitude of the electric field at the point (1 m, 2 m) is:","options":["11 V/m","8 V/m","√65 V/m","√73 V/m"],"answer":3,"explanation":"E = −∇V = −(8x î + 3 ĵ). At x = 1, E = −(8î + 3ĵ), so |E| = √(64 + 9) = √73 V/m. Adding the components (11) ignores that they are perpendicular.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-43","question":"A parallel-plate air capacitor of capacitance C₀ has plate separation 8 mm. A metal sheet 2 mm thick and a dielectric slab (K = 4) 4 mm thick, both of the full plate area, are inserted between the plates. The new capacitance is:","options":["4C₀/3","4C₀","8C₀/3","2C₀"],"answer":2,"explanation":"The metal removes 2 mm of gap, and the dielectric of thickness t acts like an air gap of t/K = 1 mm. Effective gap = 8 − 2 − 4 + 1 = 3 mm, so C = (8/3)C₀.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-44","question":"The electrostatic energy stored in an isolated conducting sphere of radius R carrying charge Q is:","options":["Q²/(16πε₀R)","3Q²/(20πε₀R)","Q²/(8πε₀R)","Q²/(4πε₀R)"],"answer":2,"explanation":"C = 4πε₀R, so U = Q²/2C = Q²/(8πε₀R). 3Q²/(20πε₀R) is the self-energy of a uniformly charged solid (non-conducting) sphere, which also has field inside.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-45","question":"Assertion (A): A charged particle released from rest in an electrostatic field always moves along the field line through its starting point.\nReason (R): The electric force on a charge acts along the tangent to the field line at its position.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"R is true, but A is false: the force gives the acceleration along the tangent, not the velocity. Once the particle has speed, on a curved field line its inertia carries it off the line; it follows the line only if the line is straight.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-electrostatics-46", "question": "Which of the following cannot be the charge on an isolated body (e = 1.6 × 10⁻¹⁹ C)?", "options": ["3.2 × 10⁻¹⁹ C", "4.8 × 10⁻¹⁹ C", "2.4 × 10⁻¹⁹ C", "1.6 × 10⁻¹⁸ C"], "answer": 2, "explanation": "Charge is quantised, q = ne with n an integer. 2.4 × 10⁻¹⁹ C would be 1.5e, which is impossible; the others are 2e, 3e and 10e.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-electrostatics-47", "question": "The dielectric constant of a metal is taken to be:", "options": ["infinite", "zero", "one", "slightly greater than one"], "answer": 0, "explanation": "Inside a conductor the electrostatic field is zero; E = E₀/K → 0 corresponds to K → ∞. A slab of metal between capacitor plates acts like a dielectric of infinite K.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-electrostatics-48", "question": "The plates of a parallel-plate capacitor are 2 mm apart and have a potential difference of 100 V between them. The electric field between the plates is:", "options": ["50 V/m", "2 × 10⁻² V/m", "2 × 10⁵ V/m", "5 × 10⁴ V/m"], "answer": 3, "explanation": "For a uniform field E = V/d = 100/(2 × 10⁻³) = 5 × 10⁴ V/m. Leaving d in millimetres gives the trap 50 V/m; inverting the ratio gives 2 × 10⁻².", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-electrostatics-49", "question": "The work done by an external agent in slowly moving a charge of 3 μC from a point at potential 10 V to a point at potential 50 V is:", "options": ["1.5 × 10⁻⁴ J", "1.2 × 10⁻⁴ J", "3 × 10⁻⁵ J", "−1.2 × 10⁻⁴ J"], "answer": 1, "explanation": "W_ext = q(V_B − V_A) = 3 × 10⁻⁶ × 40 = 1.2 × 10⁻⁴ J. The field does −1.2 × 10⁻⁴ J; 1.5 × 10⁻⁴ J wrongly uses 50 V alone.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-electrostatics-50", "question": "Treating the Earth as an isolated conducting sphere of radius 6.4 × 10⁶ m, its capacitance is about (1/4πε₀ = 9 × 10⁹ N m²/C²):", "options": ["711 F", "711 μF", "7.1 pF", "64 μF"], "answer": 1, "explanation": "C = 4πε₀R = 6.4 × 10⁶/(9 × 10⁹) ≈ 7.1 × 10⁻⁴ F ≈ 711 μF. Even a planet-sized sphere has under a millifarad, which shows how large a unit the farad is.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-electrostatics-51", "question": "A hemispherical bowl of radius R is placed in a uniform electric field E directed parallel to its axis of symmetry. The magnitude of the electric flux through its curved surface is:", "options": ["2πR²E", "4πR²E", "zero", "πR²E"], "answer": 3, "explanation": "With no charge inside, every field line crossing the flat circular face (area πR²) also crosses the curved face, so the flux is πR²E, not 2πR²E (the curved area times E).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-52", "question": "Point charges +4q and +q are fixed 3 m apart. The point on the line joining them where the electric field is zero lies:", "options": ["2 m from the +4q charge", "1 m from the +4q charge", "1.5 m from each", "6 m from the +4q charge, outside the pair"], "answer": 0, "explanation": "For like charges the null point lies between them: 4q/x² = q/(3 − x)², so 2/x = 1/(3 − x), giving x = 2 m from +4q, closer to the smaller charge.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-electrostatics-53", "question": "A thin ring of radius R carries a uniformly distributed charge. The electric field on its axis is maximum at a distance from the centre of:", "options": ["R", "√2 R", "R/√2", "R/2"], "answer": 2, "explanation": "E = kQx/(R² + x²)^(3/2). Setting dE/dx = 0 gives R² + x² = 3x², so x = R/√2. At the centre E is zero, and far away it falls as 1/x².", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-54", "question": "Two identical small conducting spheres carry charges +8 μC and −2 μC and attract each other with a force F when placed a distance r apart. They are touched together and put back at the same separation. The new force is:", "options": ["9F/16, attractive", "F/16, repulsive", "F, repulsive", "9F/16, repulsive"], "answer": 3, "explanation": "On touching, the net +6 μC divides equally: +3 μC each. F ∝ q₁q₂, so F′/F = (3 × 3)/(8 × 2) = 9/16, and the force is now repulsive since both charges are positive.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-electrostatics-55", "question": "The energy density of the electric field in a region where the field strength is 10⁵ V/m (ε₀ = 8.85 × 10⁻¹² F/m) is about:", "options": ["8.85 × 10⁻² J/m³", "4.4 × 10⁻² J/m³", "4.4 × 10⁻⁷ J/m³", "8.85 × 10⁻⁷ J/m³"], "answer": 1, "explanation": "u = ½ε₀E² = 0.5 × 8.85 × 10⁻¹² × 10¹⁰ ≈ 4.4 × 10⁻² J/m³. Dropping the ½ gives 8.85 × 10⁻²; forgetting to square E gives the 10⁻⁷ values.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-56", "question": "A solid non-conducting sphere carries a charge distributed uniformly throughout its volume. The ratio of the electric potential at its centre to that at its surface is:", "options": ["1 : 1", "2 : 3", "3 : 2", "3 : 1"], "answer": 2, "explanation": "Inside, V(r) = kQ(3R² − r²)/(2R³), so V(0) = 3kQ/2R while V(R) = kQ/R; the ratio is 3 : 2. 1 : 1 is true only for a conducting sphere, which has no field inside.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-57", "question": "A parallel-plate capacitor stays connected to a battery while the separation between its plates is halved. The energy stored in it:", "options": ["doubles", "halves", "stays the same", "becomes four times"], "answer": 0, "explanation": "V is fixed by the battery and C doubles, so U = ½CV² doubles. With the battery disconnected (Q fixed), U = Q²/2C would halve instead.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-electrostatics-58", "question": "An isolated parallel-plate air capacitor has plates of area 1 m² carrying charges ±8.85 μC (ε₀ = 8.85 × 10⁻¹² F/m). The force of attraction between the plates is about:", "options": ["8.85 N", "2.2 N", "4.4 N", "0.44 N"], "answer": 2, "explanation": "Each plate feels the field of the other plate only, σ/2ε₀, so F = Q²/(2ε₀A) = (8.85 × 10⁻⁶)²/(2 × 8.85 × 10⁻¹²) ≈ 4.4 N. Using the full field σ/ε₀ doubles it to 8.85 N.", "difficulty": "hard", "source": "JEE Advanced pattern"},
  {"id": "phy-electrostatics-59", "question": "A point charge q is placed at one corner of a cube. The electric flux through one of the three faces of the cube that do not touch that corner is:", "options": ["q/24ε₀", "q/8ε₀", "q/6ε₀", "zero"], "answer": 0, "explanation": "Eight such cubes would surround the charge, so this cube receives q/8ε₀. The three faces meeting at the corner get zero (the field runs along them), so each of the other three gets (q/8ε₀)/3 = q/24ε₀.", "difficulty": "hard", "source": "JEE Main · JEE Advanced"},
  {"id": "phy-electrostatics-60", "question": "Two large parallel plane sheets carry uniform surface charge densities +2σ and −σ. The magnitudes of the electric field between the sheets and outside them are respectively:", "options": ["σ/ε₀ and zero", "3σ/ε₀ and σ/ε₀", "σ/2ε₀ and 3σ/2ε₀", "3σ/2ε₀ and σ/2ε₀"], "answer": 3, "explanation": "Each sheet gives σ_i/2ε₀. Between them the two fields point the same way: (2σ + σ)/2ε₀ = 3σ/2ε₀. Outside they oppose: (2σ − σ)/2ε₀ = σ/2ε₀ on both sides. σ/ε₀ and zero holds only for equal and opposite charges.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-61", "question": "How many of the following statements about equipotential surfaces are correct?\n(A) The electric field at every point is perpendicular to the equipotential surface through that point.\n(B) No work is done in moving a charge along an equipotential surface.\n(C) Two different equipotential surfaces can intersect.\n(D) Equipotential surfaces drawn for equal steps of potential are closer together where the field is stronger.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and D are correct (E = −dV/dr, so a stronger field means a smaller spacing). C is wrong: at an intersection a point would have two potentials and two field directions. Three are correct.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-electrostatics-62", "question": "Charges +q, +q, −q and −q are placed at the corners A, B, C and D (in order) of a square of side a, so the two positive charges are on adjacent corners. The magnitude of the electric field at the centre of the square is (k = 1/4πε₀):", "options": ["2√2 kq/a²", "4√2 kq/a²", "zero", "4kq/a²"], "answer": 1, "explanation": "Each charge is a/√2 from the centre and gives E₀ = 2kq/a². The diagonal pairs A(+)/C(−) and B(+)/D(−) each give 2E₀ along their diagonal; these are perpendicular, so E = 2√2 E₀ = 4√2 kq/a², pointing from the positive side towards the negative side.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-63", "question": "Capacitors are connected in a bridge between points X and Y: X to P is 1 μF, P to Y is 2 μF, X to Q is 2 μF, Q to Y is 4 μF, and a 5 μF capacitor joins P and Q. The equivalent capacitance between X and Y is:", "options": ["14/9 μF", "2 μF", "3 μF", "7 μF"], "answer": 1, "explanation": "In series, voltages divide inversely to capacitance: V_XP/V_PY = 2/1 and V_XQ/V_QY = 4/2 = 2/1, so P and Q are at the same potential and the 5 μF capacitor carries no charge. C = (1 × 2)/3 + (2 × 4)/6 = 2/3 + 4/3 = 2 μF.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-64", "question": "Four charges, each 1 μC, are held at the corners of a square of side 10 cm. The work needed to assemble this arrangement from infinity is about (1/4πε₀ = 9 × 10⁹ N m²/C²):", "options": ["0.36 J", "0.13 J", "0.62 J", "0.49 J"], "answer": 3, "explanation": "There are 4 side pairs at a and 2 diagonal pairs at a√2: U = (kq²/a)(4 + 2/√2) = 0.09 × (4 + 1.414) ≈ 0.49 J. 0.36 J leaves out the diagonal pairs.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-65", "question": "Two small particles, each of mass 1 g and charge 1 μC, are held 10 cm apart on a smooth horizontal surface and released. Their speeds when they are very far apart are (1/4πε₀ = 9 × 10⁹ N m²/C²):", "options": ["≈ 9.5 m/s each", "≈ 13.4 m/s each", "≈ 6.7 m/s each", "≈ 3 m/s each"], "answer": 0, "explanation": "U = kq²/r = 9 × 10⁹ × 10⁻¹²/0.1 = 0.09 J. By symmetry and momentum conservation each particle gets 0.045 J: ½ × 10⁻³ × v² = 0.045, v = √90 ≈ 9.5 m/s. 13.4 m/s gives all the energy to one particle.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-66", "question": "Assertion (A): There is a limit to the charge that a metal sphere held in air can retain.\nReason (R): When the electric field at its surface exceeds the dielectric strength of air (about 3 × 10⁶ V/m), the surrounding air ionises and the charge leaks away.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: the surface field kQ/R² cannot exceed about 3 × 10⁶ V/m, which caps Q at about 3 × 10⁶ R²/k. Smaller spheres hold less charge, and sharp points discharge first.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-67", "question": "Match the charge distribution (List I) with how its electric field depends on the distance r (List II).\nList I: (P) point charge; (Q) infinitely long uniformly charged straight wire; (R) infinite uniformly charged plane sheet; (S) short electric dipole, at a far point on its axis.\nList II: (1) independent of r; (2) ∝ 1/r; (3) ∝ 1/r²; (4) ∝ 1/r³.", "options": ["P-3, Q-1, R-2, S-4", "P-2, Q-3, R-1, S-4", "P-3, Q-2, R-1, S-4", "P-4, Q-2, R-1, S-3"], "answer": 2, "explanation": "Point charge: kq/r². Line charge: λ/2πε₀r. Plane sheet: σ/2ε₀, independent of r. Dipole: 2kp/r³. So P-3, Q-2, R-1, S-4.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-electrostatics-68", "question": "In a region the electric field is E = 2x i N/C (x in metres). For a cube of side 1 m with one corner at the origin and its edges along the positive axes, the charge enclosed is about (ε₀ = 8.85 × 10⁻¹² F/m):", "options": ["8.85 × 10⁻¹² C", "zero", "3.54 × 10⁻¹¹ C", "1.77 × 10⁻¹¹ C"], "answer": 3, "explanation": "Only the faces at x = 0 and x = 1 m carry flux: Φ = E(1) × 1 − E(0) × 1 = 2 N m²/C. By Gauss's law q = ε₀Φ = 1.77 × 10⁻¹¹ C. A non-uniform field means the flux in and out do not cancel.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-69", "question": "Six equal charges +q sit at the vertices of a regular hexagon of side a, and then one of them is removed. The electric field at the centre of the hexagon is now (k = 1/4πε₀):", "options": ["kq/a², directed away from the vacant vertex", "kq/a², directed towards the vacant vertex", "5kq/a², directed towards the vacant vertex", "zero"], "answer": 1, "explanation": "With all six present the field at the centre is zero by symmetry. Removing +q is like adding −q at that vertex, a distance a from the centre, so the field is kq/a² pointing towards the empty vertex.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-electrostatics-70", "question": "A point charge Q is placed at the centre of an uncharged spherical conducting shell of inner radius a and outer radius b. The electric potential at a distance a/2 from the centre is (k = 1/4πε₀):", "options": ["2kQ/a", "kQ/b", "kQ(1/a + 1/b)", "kQ(2/a − 1/b)"], "answer": 2, "explanation": "Induced charges are −Q on the inner surface and +Q on the outer surface. Superposing: V = kQ/(a/2) − kQ/a + kQ/b = kQ(1/a + 1/b). 2kQ/a ignores the shell altogether.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-electrostatics-71","question":"An oil drop of mass 3.2 × 10⁻¹⁵ kg is held stationary between two horizontal plates by a vertical electric field of 5 × 10⁴ N/C (g = 10 m/s², e = 1.6 × 10⁻¹⁹ C, buoyancy neglected). The number of excess electrons on the drop is:","options":["4","8","2","40"],"answer":0,"explanation":"Balance: qE = mg, so q = 3.2 × 10⁻¹⁵ × 10 / (5 × 10⁴) = 6.4 × 10⁻¹⁹ C, which is 6.4 × 10⁻¹⁹ / 1.6 × 10⁻¹⁹ = 4 electrons. The field must point down so the force on the negative drop is upward.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-72","question":"A charge Q is spread uniformly along a thin wire bent into a semicircular arc of radius R. The electric potential at the centre of the arc is (k = 1/4πε₀):","options":["zero, since the field contributions cancel","kQ/R","kQ/(2R)","2kQ/(πR)"],"answer":1,"explanation":"Potential is a scalar and every element of the arc is at the same distance R from the centre, so V = Σ k dq/R = kQ/R, whatever the shape of the arc. 2kQ/(πR²) is the field there, and the field (not the potential) is what partly cancels.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-73","question":"A point charge +q is placed at an off-centre point inside a spherical cavity cut in an uncharged solid conducting sphere. Which statement is correct?","options":["The outer surface carries no charge because the conductor is neutral","The outer surface carries +q distributed non-uniformly, densest nearest the charge","The outer surface carries +q distributed uniformly","The inner surface of the cavity carries −q distributed uniformly"],"answer":2,"explanation":"The cavity wall gets −q, arranged non-uniformly so that the field inside the metal is zero; this screens the inside completely. The outer surface then carries +q, and since it 'sees' no field from inside, the charge spreads uniformly over the spherical outer surface.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-74","question":"A point charge q lies on the axis of a circular disc of radius R at a distance 3R/4 from the centre of the disc. The electric flux through the disc is:","options":["q/(2ε₀)","3q/(10ε₀)","2q/(5ε₀)","q/(5ε₀)"],"answer":3,"explanation":"The disc subtends a cone of half-angle θ with cos θ = (3R/4)/(5R/4) = 3/5, and the flux through it is (q/2ε₀)(1 − cos θ) = (q/2ε₀)(2/5) = q/(5ε₀). Using 1 − sin θ or forgetting the factor 1/2 gives the other values.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-75","question":"A short electric dipole of moment 1 × 10⁻⁹ C m lies along the line joining it to a point charge of 2 μC, its centre being 10 cm from the charge (k = 9 × 10⁹ N m²/C²). The magnitude of the force on the dipole is:","options":["3.6 × 10⁻² N","1.8 × 10⁻² N","zero, because a dipole feels no net force","7.2 × 10⁻² N"],"answer":0,"explanation":"The field of the point charge is non-uniform, so the net force is F = p dE/dr = p × 2kq/r³ = 1 × 10⁻⁹ × 2 × 9 × 10⁹ × 2 × 10⁻⁶ / 10⁻³ = 3.6 × 10⁻² N. 'Zero' holds only in a uniform field; dropping the factor 2 from the derivative gives 1.8 × 10⁻² N.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-76","question":"Two identical air capacitors are connected in parallel to a battery, and the battery is then removed. A slab of dielectric constant 3 is now inserted to fill one of them completely. The final electrostatic energy of the system, as a fraction of the energy before the slab was inserted, is:","options":["1/3","1/2","2/3","3/4"],"answer":1,"explanation":"Charge 2CV is conserved and the capacitance becomes C + 3C = 4C. Energy goes from (1/2)(2C)V² = CV² to (2CV)²/(2 × 4C) = CV²/2, i.e. one-half; the common voltage falls to V/2. Answering 1/3 treats the slab as if it filled both capacitors.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-77","question":"A 3 μF capacitor charged to 100 V and a 6 μF capacitor charged to 50 V are joined in parallel with the positive plate of each connected to the negative plate of the other. The heat produced in the connecting wires is:","options":["20 mJ","15 mJ","22.5 mJ","7.5 mJ"],"answer":2,"explanation":"The charges are 300 μC and 300 μC, so with opposite plates joined the net charge is 300 − 300 = 0: both capacitors end up fully discharged. All the initial energy, (1/2)(3 μF)(100)² + (1/2)(6 μF)(50)² = 15 + 7.5 = 22.5 mJ, becomes heat. Joining like plates would leave charge behind.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-78","question":"A small particle of charge −q and mass m can move along a narrow frictionless tunnel through the centre of a fixed non-conducting sphere of radius R carrying charge +Q spread uniformly through its volume. Released from rest inside the tunnel, it oscillates with period T. If the sphere is replaced by one of radius 2R with the same total charge Q, the period becomes:","options":["2T","4T","√2 T","2√2 T"],"answer":3,"explanation":"Inside the sphere E = kQr/R³, so the force is −(kQq/R³)r: simple harmonic motion with T = 2π√(mR³/kQq), independent of amplitude. T ∝ R^(3/2), so doubling R multiplies T by 2^(3/2) = 2√2.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-79","question":"An isolated conducting sphere of radius R carries charge Q. What fraction of its total electrostatic field energy is stored in the region outside a concentric sphere of radius 2R?","options":["1/2","1/8","1/4","3/4"],"answer":0,"explanation":"The field energy beyond radius r is ∫ (ε₀E²/2) 4πr² dr = kQ²/(2r). The total (beyond R) is kQ²/(2R) and beyond 2R it is kQ²/(4R): exactly one-half. 1/4 comes from comparing the field values instead of the energies.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-80","question":"An isolated conducting sphere of radius R is charged to a potential V. It is then surrounded by a thin concentric uncharged conducting shell of radius 2R, and the shell is earthed. The new potential of the inner sphere is:","options":["V","V/2","2V","zero"],"answer":1,"explanation":"The inner charge Q = 4πε₀RV stays. Earthing makes the shell carry −Q and sit at zero, so V_inner = kQ/R − kQ/(2R) = V/2. 'Zero' wrongly assumes earthing the shell also drains the inner sphere.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-81","question":"An uncharged conducting sphere of radius R is earthed through a thin wire. A point charge +q is brought to a distance 3R from its centre and held there. The charge that flows between the earth and the sphere is:","options":["q from the earth onto the sphere","q/3 from the sphere to the earth","q/3 of negative charge from the earth onto the sphere","no charge, since the sphere stays neutral"],"answer":2,"explanation":"The earthed sphere is at zero potential, and every point of it, including the centre, has the same potential: kq/(3R) + kQ/R = 0 (all induced charge Q is at distance R from the centre). So Q = −q/3, which flows up from the earth. Leaving it neutral ignores the earthing.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-82","question":"Three thin concentric conducting shells A, B and C have radii a, 2a and 3a and each carries charge +Q. Shells A and C are then joined by a thin insulated wire passing through a small hole in B. The final charge on the innermost shell A is:","options":["zero","−Q/2","+Q/2","−Q/4"],"answer":3,"explanation":"A and C must reach equal potentials with q_A + q_C = 2Q. V_A = k[q_A/a + Q/(2a) + q_C/(3a)] and V_C = k(q_A + Q + q_C)/(3a) = kQ/a. Setting them equal: q_A + Q/2 + (2Q − q_A)/3 = Q, so (2/3)q_A = −Q/6 and q_A = −Q/4. 'Zero' would hold only if B carried no charge.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-83","question":"The gap of a parallel-plate capacitor (plate area A, separation d) is filled with a dielectric whose dielectric constant increases linearly from K₀ at one plate to 2K₀ at the other. Its capacitance is:","options":["3ε₀AK₀/(2d)","2ε₀AK₀/(3d)","ε₀AK₀/(d ln 2)","ε₀AK₀ ln 2/d"],"answer":2,"explanation":"Thin layers dx are in series: 1/C = ∫ dx/(ε₀K(x)A) = (d/ε₀AK₀) ∫₀¹ du/(1 + u) = (d ln 2)/(ε₀AK₀). So C = ε₀AK₀/(d ln 2) ≈ 1.44ε₀AK₀/d. Using the average constant 1.5K₀ wrongly treats the layers as being in parallel.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-84","question":"A very long straight wire carries a uniform charge of +1 μC per metre. A small particle of mass 1 g and charge +1 μC is released from rest 1 cm from the wire. Neglecting gravity, its speed when it is 2 cm from the wire is about (1/4πε₀ = 9 × 10⁹ N m²/C²):","options":["5.0 m/s","7.1 m/s","6.0 m/s","3.5 m/s"],"answer":0,"explanation":"Potential difference between r and 2r: ΔV = (λ/2πε₀) ln 2 = 2kλ ln 2 = 2 × 9 × 10⁹ × 10⁻⁶ × 0.693 ≈ 1.25 × 10⁴ V. KE = qΔV ≈ 1.25 × 10⁻² J, so v = √(2 × 0.0125/0.001) ≈ 5.0 m/s. Dropping the ln 2 gives 6.0 m/s; using kλ instead of 2kλ gives 3.5 m/s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-85","question":"How many of the following statements about an electric dipole are correct?\n(A) In a uniform electric field the net force on it is zero.\n(B) With its moment parallel to a uniform field it is in stable equilibrium.\n(C) In a non-uniform field, a dipole whose moment is parallel to the field is pulled towards the region of stronger field.\n(D) Its potential energy in a uniform field is least when its moment is antiparallel to the field.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and C are correct (C: F = p dE/dx points up the field gradient). D is wrong: U = −pE cos θ is least (−pE) when the moment is parallel to the field and greatest (+pE) when antiparallel.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-86","question":"Assertion (A): The outward force per unit area on the surface of a charged conductor is σ²/(2ε₀), although the field just outside the surface is σ/ε₀.\nReason (R): The field acting on a small patch of the surface is due to all the other charges only, and this equals σ/(2ε₀).","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The patch's own field is σ/2ε₀ on either side; the rest of the charges give σ/2ε₀, which adds to it outside (σ/ε₀) and cancels it inside (0). The patch feels only the external σ/2ε₀, so the force per area is σ × σ/2ε₀ = σ²/2ε₀. R is exactly the reason.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-87","question":"A non-conducting sphere of radius R has charge Q spread uniformly through its volume, and a conducting sphere of the same radius carries the same charge Q. The ratio of the electrostatic energy of the non-conducting sphere to that of the conducting sphere is:","options":["1 : 1","6 : 5","5 : 6","3 : 2"],"answer":1,"explanation":"Conducting sphere: U = kQ²/(2R), all of it outside. Uniform solid sphere: U = 3kQ²/(5R) = kQ²/(2R) outside + kQ²/(10R) inside. Ratio = (3/5)/(1/2) = 6 : 5; the extra is the field energy inside the volume.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-88","question":"Three initially uncharged capacitors of 1 μF, 2 μF and 3 μF have one plate each joined at a common node N. Using batteries, the other plates of the 1 μF, 2 μF and 3 μF capacitors are held at 0 V, 10 V and 20 V respectively. The charge on the 3 μF capacitor is:","options":["10 μC","30 μC","20 μC","60 μC"],"answer":2,"explanation":"The isolated node starts neutral, so Σ C(V_i − V_N) = 0: V_N = (1 × 0 + 2 × 10 + 3 × 20)/6 ≈ 13.33 V. Charge on 3 μF = 3 × (20 − 13.33) = 20 μC (check: 13.33 + 6.67 = 20 μC on the other two). 60 μC wrongly takes the node at 0 V.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-89","question":"A thin rod of length L carries a uniform positive charge. Point P lies on the line perpendicular to the rod through one of its ends, at a distance L from that end. The electric field at P makes an angle with this perpendicular line of:","options":["0°","30°","45°","22.5°"],"answer":3,"explanation":"For a finite rod seen from P, E_perp = (kλ/L) sin θ and E_parallel = (kλ/L)(1 − cos θ), where θ = 45° is the angle the rod subtends at P. tan φ = (1 − cos 45°)/sin 45° = tan 22.5°, so the field bisects the angle subtended by the rod. Answering 45° wrongly aims the field along the line to the far end.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-90","question":"A non-conducting sphere of radius R has a volume charge density ρ = ρ₀r/R, where r is the distance from the centre. The ratio of the electric field at r = R/2 to that at r = 2R is:","options":["1 : 1","1 : 2","2 : 1","1 : 4"],"answer":0,"explanation":"Charge within r < R: q(r) = ∫ρ₀(r/R)4πr² dr = πρ₀r⁴/R, so E = kq/r² ∝ r² inside: E(R/2) = E(R)/4. Outside, E ∝ 1/r²: E(2R) = E(R)/4. The two are equal. Assuming E ∝ r inside (uniform sphere) gives 2 : 1.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-91","question":"Three identical large parallel metal plates 1, 2 and 3 (area A) are placed in that order with a gap d between neighbours. They carry charges Q, 2Q and 3Q respectively and are isolated. The magnitude of the potential difference between plates 1 and 3 is:","options":["Qd/(Aε₀)","2Qd/(Aε₀)","3Qd/(Aε₀)","4Qd/(Aε₀)"],"answer":1,"explanation":"Each outer face carries half the total, 3Q. Then plate 1's inner face has Q − 3Q = −2Q, plate 2's faces have +2Q and 0, and plate 3's inner face has 0. The field is 2Q/(Aε₀) between plates 1 and 2 and zero between 2 and 3, so |V₁ − V₃| = 2Qd/(Aε₀). Assuming equal fields in both gaps gives 4Qd/(Aε₀).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-92","question":"A parallel-plate capacitor whose air capacitance is 2 μF is completely filled with a slab of dielectric constant 3 and stays connected to a 100 V battery. The slab is pulled out slowly. The work done by the external agent is:","options":["−0.02 J","+0.04 J","+0.02 J","+0.06 J"],"answer":2,"explanation":"ΔU = (1/2)(2 μF)(100)² − (1/2)(6 μF)(100)² = −0.02 J. Charge 400 μC is pushed back into the battery, so the battery's work is −400 μC × 100 V = −0.04 J. W_agent = ΔU − W_battery = −0.02 + 0.04 = +0.02 J: the slab is pulled in by the field, so the agent must do positive work. −0.02 J forgets the battery.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-93","question":"A thin hemispherical shell of radius R carries a uniform surface charge density σ. The magnitude of the electric field at the centre of its circular rim (the centre of the sphere) is:","options":["σ/(2ε₀)","σ/ε₀","σ/(8ε₀)","σ/(4ε₀)"],"answer":3,"explanation":"A ring at polar angle θ has charge σ2πR² sin θ dθ, and only the axial components survive: E = ∫₀^(π/2) (σ2πR² sin θ cos θ dθ)/(4πε₀R²) = (σ/2ε₀)(1/2) = σ/(4ε₀). σ/(2ε₀) forgets the cos θ projection.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-94","question":"A charge Q is spread uniformly along a thin rod of length L. A point charge q is brought slowly from infinity to a point on the line of the rod, at a distance L beyond its nearer end. The work done is (k = 1/4πε₀):","options":["(kQq/L) ln 2","kQq/(2L)","(kQq/L) ln (3/2)","2kQq/(3L)"],"answer":0,"explanation":"V = ∫ kλ dx/x from L to 2L = (kQ/L) ln 2, so W = qV = (kQq/L) ln 2 ≈ 0.69kQq/L. Treating the rod as a point charge at its centre (distance 1.5L) gives the trap 2kQq/(3L) ≈ 0.67kQq/L.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-95","question":"Two identical small charged balls hang from a common point on equal insulating threads and separate so that each thread makes an angle θ with the vertical. When the whole set-up is immersed in a liquid of density 900 kg/m³ and dielectric constant 3, the angle stays exactly θ. The density of the material of the balls is:","options":["1800 kg/m³","1350 kg/m³","2700 kg/m³","1200 kg/m³"],"answer":1,"explanation":"tan θ = F/(effective weight). In the liquid the electric force becomes F/K and the effective weight mg(1 − ρ_l/ρ). Equal angles need K(1 − ρ_l/ρ) = 1, so ρ = Kρ_l/(K − 1) = 3 × 900/2 = 1350 kg/m³. Ignoring buoyancy makes the condition impossible; using Kρ_l gives 2700.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-electrostatics-96","question":"The SI unit of the permittivity of free space ε₀ is:","options":["N C⁻² m⁻²","N m² C⁻²","C N⁻¹ m⁻¹","C² N⁻¹ m⁻²"],"answer":3,"explanation":"From Coulomb's law F = q₁q₂/(4πε₀r²), ε₀ = q₁q₂/(4πFr²), with units C²/(N m²) = C² N⁻¹ m⁻². N m² C⁻² is the unit of 1/(4πε₀).","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-electrostatics-97","question":"A point charge is carried once around a closed path in an electrostatic field. The net work done by the electrostatic field on it is:","options":["negative","positive","zero","equal to the charge times the field strength"],"answer":2,"explanation":"The electrostatic field is conservative: its work depends only on the end points. On a closed path the end points coincide, so the net work is zero (∮E·dl = 0).","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-electrostatics-98","question":"Two equal charges +Q are fixed at (−a, 0) and (a, 0). A small test charge is moved along the y-axis. The magnitude of the electric force on it is maximum at:","options":["y = a","y = a/√2","y = a/2","y = √2a"],"answer":1,"explanation":"On the y-axis, E = 2kQy/(a² + y²)^(3/2). Setting dE/dy = 0 gives a² + y² = 3y², i.e. y = a/√2.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-99","question":"Charges q, 2q, 3q and 4q are placed in order at the four corners of a square of side a. The magnitude of the electric field at the centre of the square is (k = 1/4πε₀):","options":["4√2 kq/a²","2√2 kq/a²","20 kq/a²","zero"],"answer":0,"explanation":"Each corner is a/√2 from the centre, so a charge nq gives 2nkq/a². Along one diagonal q and 3q partly cancel to a net 2q-equivalent; along the other, 2q and 4q leave 2q-equivalent. The two perpendicular resultants are each 4kq/a², giving 4√2 kq/a².","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-100","question":"A short electric dipole of moment p lies along the line joining it to a point charge Q, at a large distance r from it. The magnitude of the force between them is (k = 1/4πε₀):","options":["2kQp/r³","kQp/r³","kQp/r²","2kQp/r²"],"answer":0,"explanation":"The charge Q sits on the dipole's axis, where the dipole's field is 2kp/r³. The force on Q is therefore 2kQp/r³, and by Newton's third law the dipole feels the same force. It falls off as 1/r³, faster than between point charges.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-101","question":"Two small balls, each of mass m, carry charges +q and −q and are joined by a light insulating rod of length d to form a dipole. It is pivoted at its centre in a uniform electric field E and slightly displaced from its equilibrium orientation. The period of small angular oscillations is:","options":["2π√(m/(qE d))","2π√(md/(qE))","2π√(2md/(qE))","2π√(md/(2qE))"],"answer":3,"explanation":"Moment of inertia about the centre: I = 2m(d/2)² = md²/2. Restoring torque = pE sin θ ≈ qdEθ. So ω² = qdE/(md²/2) = 2qE/(md), and T = 2π√(md/(2qE)).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-102","question":"A parallel-plate air capacitor has capacitance C₀ and plate separation d. A metal slab of thickness d/3 and a dielectric slab of thickness d/3 and dielectric constant 2, both of the full plate area, are inserted between the plates. The new capacitance is:","options":["3C₀","1.5C₀","2C₀","1.2C₀"],"answer":2,"explanation":"A metal slab removes its thickness from the gap; a dielectric of thickness t acts like air of thickness t/K. Effective air gap = d − d/3 − d/3 + (d/3)/2 = d/2. So C = ε₀A/(d/2) = 2C₀.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-103","question":"A 5 μF air capacitor stays connected to a 20 V battery while a slab of dielectric constant 3, filling the gap, is slowly pushed in. During the insertion, the work done by the external agent (who controls the slab so that it moves slowly) is:","options":["+2 mJ","−2 mJ","+4 mJ","zero"],"answer":1,"explanation":"Extra charge drawn: ΔQ = (K − 1)C₀V = 200 μC, so the battery does ΔQ·V = 4 mJ of work. The stored energy rises by ½(K − 1)C₀V² = 2 mJ. Energy balance: W_battery + W_agent = ΔU, so W_agent = 2 − 4 = −2 mJ. The field pulls the slab in and the agent must hold it back.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-104","question":"A spherical cavity is cut out of a uniformly charged non-conducting sphere (charge density ρ); the cavity's centre is at a displacement d from the sphere's centre. The electric field inside the cavity is:","options":["zero everywhere","uniform, of magnitude ρd/(3ε₀), parallel to the line joining the centres","radial from the cavity's centre, growing with distance","uniform, of magnitude ρd/ε₀"],"answer":1,"explanation":"Treat the cavity as the full sphere (+ρ) plus a small sphere of −ρ. Inside, the fields are ρr/(3ε₀) and −ρr′/(3ε₀), whose sum is ρ(r − r′)/(3ε₀) = ρd/(3ε₀), the same vector at every point of the cavity.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-105","question":"A small positive charge q is placed at the midpoint between two equal positive charges +Q fixed a distance apart. Considering small displacements of q, its equilibrium is:","options":["stable for displacements along the line joining the charges, but unstable for displacements perpendicular to it","stable in all directions","unstable in all directions","unstable along the line but stable perpendicular to it"],"answer":0,"explanation":"Along the line, moving towards one charge increases its repulsion, pushing q back: stable. Perpendicular to the line, the two repulsions acquire components pushing q further away: unstable. (Earnshaw's theorem forbids stability in every direction.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-106","question":"An uncharged capacitor C is charged by connecting it to a battery of emf V through a resistor R. When charging is complete, the heat produced in the resistor is:","options":["zero if R is very small","CV²","½CV² × R/(R + 1 Ω)","½CV², independent of R"],"answer":3,"explanation":"The battery does work QV = CV², and the capacitor stores ½CV². The remaining ½CV² is dissipated as heat whatever the value of R; a smaller R only makes it happen faster.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-electrostatics-107","question":"The gap (separation d) of a parallel-plate capacitor of air capacitance C₀ is filled with a dielectric whose constant increases linearly from 1 at one plate to e (≈ 2.718) at the other. The capacitance becomes about:","options":["2.72C₀","1.86C₀","1.72C₀","1.36C₀"],"answer":2,"explanation":"The layers are in series: 1/C = ∫dx/(ε₀AK(x)) with K = 1 + (e − 1)x/d. The integral is d ln(e)/[(e − 1)ε₀A], so C = (e − 1)ε₀A/d ≈ 1.72C₀. Using the average K, (1 + e)/2 ≈ 1.86, is the trap.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-108","question":"A spherical capacitor consists of two concentric thin metal shells of radii 10 cm and 20 cm, with air between them. Its capacitance is about (1/4πε₀ = 9 × 10⁹ N m² C⁻²):","options":["33 pF","11 pF","22 pF","2.2 pF"],"answer":2,"explanation":"C = 4πε₀ab/(b − a) = (0.1 × 0.2/0.1)/(9 × 10⁹) = 0.2/(9 × 10⁹) ≈ 2.2 × 10⁻¹¹ F = 22 pF.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-electrostatics-109","question":"A thin conducting shell of radius 3a carries charge Q. A conducting sphere of radius a, concentric with it, is connected to the earth by a thin wire passing through a tiny hole in the shell. The charge on the inner sphere is:","options":["−Q","−Q/3","zero","−3Q"],"answer":1,"explanation":"Earthing makes the inner sphere's potential zero: kq/a + kQ/(3a) = 0 (the shell's potential is uniform inside it). So q = −Q/3. Only part of the shell's charge is 'neutralised', because the inner sphere is not enclosing the shell.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-110","question":"Two point charges are a distance r apart in vacuum and repel with force F₀. A dielectric slab (K = 4) of thickness r/2 is placed between them, with its faces perpendicular to the line joining them. The force between them becomes approximately:","options":["4F₀/9","F₀/4","F₀/2","16F₀/25"],"answer":0,"explanation":"A slab of thickness t and constant K acts like an extra distance: the effective separation is (r − t) + t√K = r/2 + r = 1.5r. So F = F₀/(1.5)² = 4F₀/9.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-111","question":"The electric potential in a region is V = (6xy − y + 2yz) volt, with x, y, z in metres. The magnitude of the electric field at the point (1 m, 1 m, 0) is:","options":["√37 V/m","√61 V/m","9 V/m","√65 V/m ≈ 8.1 V/m"],"answer":3,"explanation":"E = −∇V: Eₓ = −6y = −6, E_y = −(6x − 1 + 2z) = −5, E_z = −2y = −2 at the point. |E| = √(36 + 25 + 4) = √65 ≈ 8.1 V/m.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-112","question":"A uniform electric field of 100 V/m points along +x. The potential at the point (3 m, 4 m) minus that at the origin is:","options":["−400 V","−500 V","+300 V","−300 V"],"answer":3,"explanation":"V(B) − V(A) = −∫E·dl = −Eₓ Δx = −100 × 3 = −300 V. Only the displacement along the field matters; the 4 m along y is along an equipotential.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-electrostatics-113","question":"Two small particles of masses 1 g and 2 g, each with charge 1 μC, are held 10 cm apart on a smooth horizontal insulating surface and released. The final speed of the 1 g particle (1/4πε₀ = 9 × 10⁹ N m² C⁻²) is about:","options":["7.7 m/s","13.4 m/s","11 m/s","5.5 m/s"],"answer":2,"explanation":"Initial PE = kq²/r = 0.09 J becomes KE. Momentum: m₁v₁ = m₂v₂, so v₂ = v₁/2. ½(10⁻³)v₁² + ½(2 × 10⁻³)(v₁/2)² = 0.09 gives 0.75 × 10⁻³ v₁² = 0.09, so v₁ = √120 ≈ 11 m/s.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-114","question":"Two identical 4 μF air capacitors are connected in series across a 12 V battery. With the battery still connected, the gap of one of them is completely filled with a dielectric of constant 2. The potential difference across the OTHER capacitor becomes:","options":["6 V","8 V","4 V","12 V"],"answer":1,"explanation":"Now the capacitances are 8 μF and 4 μF in series: C = 8/3 μF and Q = 32 μC. The voltages divide inversely to C: 32/4 = 8 V across the unfilled capacitor and 4 V across the filled one.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-115","question":"A thin rod lies along the x-axis from x = 0 to x = L and carries a non-uniform linear charge density λ = λ₀x/L. The electric potential at the origin is (k = 1/4πε₀):","options":["kλ₀","kλ₀/2","kλ₀ ln 2","2kλ₀"],"answer":0,"explanation":"V = ∫k dq/x = ∫₀ᴸ k(λ₀x/L)dx/x = kλ₀(L/L) = kλ₀. The 1/x of the potential exactly cancels the growth of the density.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-116","question":"The total electrostatic self-energy of a non-conducting sphere of radius R with charge Q spread uniformly through its volume is (k = 1/4πε₀):","options":["3kQ²/5R","kQ²/2R","kQ²/R","3kQ²/10R"],"answer":0,"explanation":"Build it up shell by shell: dU = k q(r) dq/r with q(r) = Qr³/R³. Integrating gives U = 3kQ²/(5R), larger than the kQ²/2R of a conducting sphere (where all the charge sits at the surface).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-117","question":"A point charge q is placed exactly at the centre of one face of a closed cube. The total electric flux through the cube is:","options":["zero","q/ε₀","q/(6ε₀)","q/(2ε₀)"],"answer":3,"explanation":"Place a second identical cube against that face: together they enclose q completely, with flux q/ε₀, shared equally by symmetry. So one cube receives q/(2ε₀).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-118","question":"A metal sphere of radius 10 cm is placed in air, whose dielectric strength is 3 × 10⁶ V/m. The maximum potential to which the sphere can be raised before the surrounding air breaks down is:","options":["3 × 10⁶ V","3 × 10⁷ V","3 × 10⁵ V","3 × 10⁴ V"],"answer":2,"explanation":"The field at the surface is E = V/R (since E = kQ/R² and V = kQ/R). Breakdown occurs when V/R reaches 3 × 10⁶ V/m, so V_max = 3 × 10⁶ × 0.1 = 3 × 10⁵ V. Larger spheres can hold higher potentials.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-119","question":"A large plane sheet carries a uniform surface charge density σ, except for a circular hole of radius R cut out of it. The electric field at a point on the axis of the hole, at a distance R from the plane, has magnitude:","options":["σ/(2ε₀)","σ/(2√2ε₀)","σ/(√2ε₀)","zero"],"answer":1,"explanation":"Superpose a complete sheet (σ/2ε₀) and a disc of −σ. The disc's axial field is (σ/2ε₀)[1 − x/√(x² + R²)]. The difference is (σ/2ε₀)x/√(x² + R²) = (σ/2ε₀)(1/√2) at x = R.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-120","question":"Charges +4q and −q are fixed on the x-axis at x = 0 and x = 3 m. Apart from infinity, the electric potential on the x-axis is zero at:","options":["x = 6 m only","x = 2.4 m and x = 4 m","x = 2 m only","x = 2.4 m only"],"answer":1,"explanation":"V = k[4q/|x| − q/|x − 3|] = 0 requires |x| = 4|x − 3|. Between the charges: x = 4(3 − x) gives x = 2.4 m. Beyond −q: x = 4(x − 3) gives x = 4 m. (Zero FIELD occurs elsewhere, at x = 6 m.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-121","question":"A 10 μF parallel-plate capacitor is charged to 100 μC and disconnected from the battery. The plates are then slowly pulled apart until their separation is doubled. The work done by the external agent is:","options":["0.5 mJ","1 mJ","0.25 mJ","zero"],"answer":0,"explanation":"With Q fixed, U = Q²/2C, and C halves, so U doubles from 0.5 mJ to 1 mJ. The agent works against the attraction of the plates, supplying the 0.5 mJ increase.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-electrostatics-122","question":"A charge is carried from one point to another along the perpendicular bisector (equatorial line) of an electric dipole. The work done by the dipole's field is:","options":["dependent on the distance moved","positive","negative","zero"],"answer":3,"explanation":"Every point on the equatorial plane is equidistant from +q and −q, so the potential there is zero. Moving between two points of equal potential requires no work, even though the field is not zero there.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-electrostatics-123","question":"A charge q is fixed at x = 0 and a charge 4q at x = L. A third charge Q is to be placed so that ALL three charges are in equilibrium. Then Q and its position are:","options":["+4q/9, at x = L/3","−4q/9, at x = 2L/3","−4q/9, at x = L/3","−q/9, at x = L/3"],"answer":2,"explanation":"For Q itself: kq/x² = k(4q)/(L − x)², giving x = L/3. For q to be in equilibrium: kQ/(L/3)² must cancel k(4q)/L², so |Q| = 4q/9, and it must be negative to pull q towards it. (Check: 4q is then also in equilibrium.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-124","question":"A thin spherical shell of radius R carries a uniform surface charge density σ. The electrostatic force per unit area on the shell's own surface charge is due to a field of magnitude:","options":["zero, the field just inside","σ/ε₀, the field just outside","σ/(2ε₀), the average of the fields just inside and just outside","σ/(4ε₀)"],"answer":2,"explanation":"A surface element does not push on itself. The field of the rest of the shell at that element is the average of the inside (0) and outside (σ/ε₀) values, σ/(2ε₀). This gives the outward pressure σ²/(2ε₀).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-125","question":"Five identical metal plates, each of area A, are placed parallel to one another with equal gaps d (air). Plates 1, 3 and 5 are connected together to one terminal and plates 2 and 4 to the other. The capacitance between the terminals is:","options":["5ε₀A/d","4ε₀A/d","ε₀A/(4d)","2ε₀A/d"],"answer":1,"explanation":"Each of the four gaps is a capacitor ε₀A/d, and the interleaved connections place all four in parallel between the two terminals. C = 4ε₀A/d.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-electrostatics-126","question":"A thin hemispherical shell of radius R carries a total charge Q spread uniformly over it. The electric potential at the centre of the flat (open) side is (k = 1/4πε₀):","options":["kQ/R","kQ/2R","2kQ/R","3kQ/2R"],"answer":0,"explanation":"Every element of charge is at the same distance R from the centre, and potential is a scalar sum. So V = kQ/R, exactly as for a full shell with the same charge, though the field there is not zero.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-127","question":"An uncharged, large flat metal plate is placed perpendicular to a uniform electric field of 1 × 10⁵ V/m. The magnitude of the charge per unit area induced on each face of the plate is about (ε₀ = 8.85 × 10⁻¹² C² N⁻¹ m⁻²):","options":["8.85 × 10⁻¹² C/m²","4.4 × 10⁻⁷ C/m²","1.77 × 10⁻⁶ C/m²","8.85 × 10⁻⁷ C/m²"],"answer":3,"explanation":"Inside the metal the field must vanish. The induced charges ±σ on the two faces produce a field σ/ε₀ inside (like a capacitor), which must cancel E. So σ = ε₀E = 8.85 × 10⁻⁷ C/m² (positive on one face, negative on the other).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-electrostatics-128","question":"A soap bubble is given an electric charge (of either sign). As a result, the bubble:","options":["expands if the charge is positive but contracts if it is negative","contracts","stays the same size","expands"],"answer":3,"explanation":"The charge spreads over the surface and the like charges repel each other, giving an outward electrostatic pressure σ²/(2ε₀) whatever the sign. The bubble expands until surface tension and the gas pressure again balance.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-electrostatics-129","question":"A point charge q is held at a distance d from a very large, flat, earthed conducting plate. The force of attraction between the charge and the plate is (k = 1/4πε₀):","options":["kq²/(2d²)","kq²/d²","kq²/(4d²)","zero, as the plate is earthed"],"answer":2,"explanation":"The induced charge on the plate produces, in the region of q, the same field as an image charge −q at distance d behind the plate. The separation is 2d, so F = kq²/(2d)² = kq²/(4d²).","difficulty":"very-hard","source":"JEE Advanced pattern"},
];

export default questions;
